/**
 * * Write a JavaScript function to remove first and last occurrence of a given character from the string.
 *
 * > removeOcc("hello", "l")
 * "heo"
 * > removeOcc("abcda", "a")
 * "bcd"
 * > removeOcc("PHP", "P")
 * "H"
 */
function removeOcc(s, ch) {
  let firstIndex = s.indexOf(ch);
  let lastIndex = s.lastIndexOf(ch);
  if (firstIndex === lastIndex) {
    return s.slice(0, firstIndex) + s.slice(firstIndex + 1);
  }
  return s.slice(0, firstIndex) + s.slice(firstIndex + 1, lastIndex) + s.slice(lastIndex + 1);
}
/**
