 * [[-2, 4, -5], [1, -1, 1], [1, 2, 3]]
 * > sortMatrix([[5, 8, 9], [6, 4, 3], [2, 1, 4]])
 * [[2, 1, 4], [6, 4, 3], [5, 8, 9]]
 */
function sortMatrix(m) {
  const sorted = m.sort((a, b) => a.reduce((acc, cur) => acc + cur) - b.reduce((acc, cur) => acc + cur));
  return sorted;
}
/**
