 * [["one", 4], ["two", 2], ["three", 2], ["four", 1]]
 * > countCommon(["Facebook", "Apple", "Amazon", "Netflix", "Google", "Apple", "Netflix", "Amazon"])
 * [["Apple", 2], ["Amazon", 2], ["Netflix", 2], ["Facebook", 1]]
 */
function countCommon(words) {
  const map = new Map();
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (map.has(word)) {
      map.set(word, map.get(word) + 1);
    } else {
      map.set(word, 1);
    }
  }
  const arr = Array.from(map);
  arr.sort((a, b) => b[1] - a[1]);
  return arr;
}
