 * true
 * > isWoodall(254)
 * false
 * > isWoodall(200)
 * false
 */
function isWoodall(x) {
  let sum = 0;
  let num = x;

  while (num > 0) {
    sum += Math.pow(num % 10, 3);
    num = Math.floor(num / 10);
  }

  return sum === x;
}
