  for (let i = 0; i < arr.length; i++) {
    if (map[arr[i]]) {
      map[arr[i]]++;
    } else {
      map[arr[i]] = 1;
    }
  }

  for (let key in map) {
    if (map[key] === 1) {
      product *= parseInt(key);
