 * * Write a JavaScript function to find binomial co-efficient.
 *
 * > binomialCoeff(5, 2)
 * 10
 * > binomialCoeff(4, 3)
 * 4
 * > binomialCoeff(3, 2)
 * 3
 */
function binomialCoeff(n, k) {
  if (k > n) {
    return -1;
