  const map = {};
  for (let i = 0; i < s.length; i++) {
    if (map[s[i]]) {
      map[s[i]]++;
    } else {
      map[s[i]] = 1;
    }
  }
  const arr = [];
  for (let key in map) {
    arr.push({ key, value: map[key] });
  }
  arr.sort((a, b) => b.value - a.value);
  const result = [];
  while (arr.length) {
    const { key, value } = arr.shift();
    if (value % 2 === 0) {
      result.push(key, key);
    } else {
      if (arr.length) {
        const { key: key2, value: value2 } = arr.shift();
        if (value2 % 2 === 0) {
          result.push(key, key2, key2, key);
        } else {
          result.push(key, key2, key, key2);
        }
      } else {
        result.push(key, key);
      }
    }
  }
  return result.join("");
}
