 * 1
 * > first([1, 2, 3], 1, 3)
 * 0
 */
function first(arr, x, n) {
  let start = 0;
  let end = n - 1;

  while (start <= end) {
    let mid = Math.floor((start + end) / 2);

    if (arr[mid] === x) {
      while (arr[mid - 1] === x) {
        mid--;
      }
      return mid;
    }

    if (arr[mid] > x) {
      end = mid - 1;
    } else {
      start = mid + 1;
    }
  }

  return -1;
}
