 * * Write a function to find the longest palindromic subsequence in the given string.
 *
 * > lps("TENS FOR TENS")
 * 5
 * > lps("CARDIO FOR CARDS")
 * 7
 * > lps("PART OF THE JOURNEY IS PART")
 * 9
 */
function lps(str) {
  const n = str.length;
  const dp = Array(n)
    .fill(0)
    .map(() => Array(n).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      if (i === j) {
        dp[i][j] = 1;
      } else if (str[i] === str[j]) {
        dp[i][j] = dp[i + 1][j - 1] + 2;
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
      }
    }
  }

  return dp[0][n - 1];
}
