/**
 * * Write a function to find the maximum product subarray of the given array.
 *
 * > maxSubarrayProduct([1, -2, -3, 0, 7, -8, -2])
 * 112
 * > maxSubarrayProduct([6, -3, -10, 0, 2])
 * 180
 * > maxSubarrayProduct([-2, -40, 0, -2, -3])
 * 80
 */
function maxSubarrayProduct(arr) {
  let max = arr[0];
  let min = arr[0];
  let result = arr[0];

  for (let i = 1; i < arr.length; i++) {
    let current = arr[i];
    let currentMax = Math.max(current, Math.max(current * max, current * min));
    let currentMin = Math.min(current, Math.min(current * max, current * min));

    max = currentMax;
    min = currentMin;
    result = Math.max(result, currentMax);
  }

  return result;
}
