 * 2
 * > findPeak([2, 3, 4, 5, 6], 5)
 * 4
 * > findPeak([8, 9, 11, 12, 14, 15], 6)
 * 5
 */
function findPeak(arr, n) {
  let start = 0;
  let end = n - 1;

  while (start < end) {
    let mid = Math.floor((start + end) / 2);

    if (arr[mid] < arr[mid + 1]) {
      start = mid + 1;
    } else {
      end = mid;
    }
  }

  return start;
}
