 * 50265600
 * > maxProduct([10, 22, 9, 33, 21, 50, 41, 60], 8)
 * 21780000
 */
function maxProduct(arr, n) {
  if (n === 1) {
    return arr[0];
  }

  let max = -Infinity;
  let temp = 1;

  for (let i = 0; i < n; i++) {
