}
/**
 * * Write a function to find the maximum profit earned from a maximum of k stock transactions
 *
 * > maxProfit([1, 5, 2, 3, 7, 6, 4, 5], 3)
 * 10
 * > maxProfit([2, 4, 7, 5, 4, 3, 5], 2)
 * 7
 * > maxProfit([10, 6, 8, 4, 2], 2)
 * 2
 */
function maxProfit(price, k) {
  const n = price.length;
  const dp = new Array(n + 1).fill(0).map(() => new Array(k + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= k; j++) {
      const prev = dp[i - 1][j];
      const prevBuy = dp[i - 1][j - 1] - price[i - 1];
      const prevSell = dp[i - 1][j] + price[i - 1];
      dp[i][j] = Math.max(prev, Math.max(prevBuy, prevSell));
    }
  }

  return dp[n][k];
}
